namespace ROM.EditorTools
{
    [InitializeOnLoad]public static class RiftJournalProbe
    {
        const string Key="ROM.JournalProbe",Folder="Documentation/quest-system";
        static int step;static double began,next,bossDeadline;static List<string> report;static string testId,testName;static Keyboard keyboard,originalKeyboard;static Mouse mouse,originalMouse;static Vector2 point;static RiftVillageNpc iria,bram,alma;static Health dummy;static RiftEncounter encounter,boss;static RiftCheckpoint[] crystals;static bool keyHadActive;
        static RiftJournalProbe(){EditorApplication.playModeStateChanged+=Changed;}
        public static void Run(){Directory.CreateDirectory(Folder);RiftJournalBuilder.Build();SessionState.SetString(Key+"Id",Guid.NewGuid().ToString("N"));SessionState.SetString(Key+"Name",UserSettings.UserNickname);SessionState.SetInt(Key+"Skin",UserSettings.CharacterSkinID);SessionState.SetInt(Key+"Combat",PlayerPrefs.GetInt(AbilityController.Preference,0));SessionState.SetString(Key+"Active",PlayerPrefs.GetString("ROM.Character.ActiveId",""));SessionState.SetBool(Key,true);EditorSceneManager.OpenScene(ProjectSceneCleanup.Menu);EditorApplication.isPlaying=true;}
        static void Changed(PlayModeStateChange state){if(!SessionState.GetBool(Key,false))return;if(state==PlayModeStateChange.EnteredPlayMode){testId=SessionState.GetString(Key+"Id","");testName="QuestProbe_"+testId.Substring(0,8);RiftJournalPlayer.StorageOverride=Folder+"/test-"+testId;report=new List<string>();step=0;began=EditorApplication.timeSinceStartup;next=began+3;EditorApplication.update+=Tick;}if(state==PlayModeStateChange.EnteredEditMode){SessionState.SetBool(Key,false);PlayerPrefs.SetInt(AbilityController.Preference,SessionState.GetInt(Key+"Combat",0));UserSettings.UserNickname=SessionState.GetString(Key+"Name","");UserSettings.CharacterSkinID=SessionState.GetInt(Key+"Skin",1);PlayerPrefs.SetString("ROM.Character.ActiveId",SessionState.GetString(Key+"Active",""));PlayerPrefs.SetString("_playerPrefs_Username",UserSettings.UserNickname);PlayerPrefs.Save();RiftJournalPlayer.StorageOverride=null;EditorApplication.Exit(SessionState.GetInt(Key+"Result",1));}}
        static void Check(bool value,string message){if(!value)throw new Exception(message);report.Add("PASS "+message);}
        static void Advance(double delay=.35){step++;next=EditorApplication.timeSinceStartup+delay;}
        static void MouseAt(Vector2 pointer,ushort buttons=0)=>InputSystem.QueueStateEvent(mouse,new MouseState{position=pointer,buttons=buttons});
        static void Press(params UnityEngine.InputSystem.Key[] keys)=>InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));
        static Button ButtonWith(Transform root,string text)=>root.GetComponentsInChildren<Button>().First(b=>b.GetComponentInChildren<Text>()?.text.StartsWith(text)==true);
        static void Near(CharacterInstance actor,RiftVillageNpc npc){RiftVillageUI.Instance.Close();actor.ServerTeleport(npc.transform.position-Vector3.forward*3,0);RiftMMOController.Instance.CameraYaw=actor.Input.LookY=0;RiftMMOController.Instance.CameraPitch=12;}
        static void Tick(){try{
            if(EditorApplication.timeSinceStartup-began>240)throw new Exception("Timeout journal step "+step);if(EditorApplication.timeSinceStartup<next)return;
            if(step==0){var hub=UnityEngine.Object.FindFirstObjectByType<RiftHub>();if(!hub||!hub.Stage||!hub.Stage.Ready)return;typeof(RiftHub).GetField("homePanel",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(hub,"Menu");hub.Navigate(HubPage.Home);Check(new[]{"MISIONES","LOGROS","AJUSTES"}.All(label=>hub.GetComponentsInChildren<Button>().Any(b=>b.GetComponentInChildren<Text>()?.text==label)),"Main menu exposes correctly labelled journal, achievements and settings");hub.ApplyActiveCharacter();PlayerPrefs.SetString("ROM.Character.ActiveId",testId);UserSettings.UserNickname=testName;UserSettings.CharacterSkinID=1;PlayerPrefs.SetInt(AbilityController.Preference,2);hub.Creator.BotsToggle.isOn=false;hub.Creator.HostGameButton.onClick.Invoke();Advance(17);return;}
            var actor=ClientFrontend.OwnedCharacterInstance;var player=ClientFrontend.ClientPlayerInstance;var hud=UnityEngine.Object.FindFirstObjectByType<RiftGameplayHUD>();var input=RiftMMOController.Instance;var journal=player?player.GetComponent<RiftJournalPlayer>():null;if(!actor||!journal||journal.State==null||!hud||!input)return;var combat=player.GetComponent<AbilityController>();var world=ROM.Horde.Horde.Instance;var camera=GameplayCamera._instance.GetComponent<Camera>();
            switch(step){
            case 1:
                Check(journal.Catalog.Quests.Length==4&&journal.Catalog.Achievements.Length==7,"Four typed quest definitions and seven achievement definitions load");Check(journal.State.CharacterId==testId,"Journal uses stable selected character identity");Check(hud.TargetPanel.anchorMin==new Vector2(0,1)&&hud.TargetPanel.anchoredPosition.x<50,"Target frame is outside center, below top-left world info");
                iria=UnityEngine.Object.FindObjectsByType<RiftVillageNpc>(FindObjectsSortMode.None).First(n=>n.Id=="iria");bram=UnityEngine.Object.FindObjectsByType<RiftVillageNpc>(FindObjectsSortMode.None).First(n=>n.Id=="bram");alma=UnityEngine.Object.FindObjectsByType<RiftVillageNpc>(FindObjectsSortMode.None).First(n=>n.Id=="alma");Check(new[]{iria,bram,alma}.All(n=>n.Target&&!n.GetComponent<Health>()),"All village NPCs are friendly targets without fake combat health");Check(RiftJournalView.Offer("iria")=="!","Initial quest is discoverable on Iria");
                SessionState.SetInt(Key+"Background",(int)InputSystem.settings.backgroundBehavior);SessionState.SetInt(Key+"Editor",(int)InputSystem.settings.editorInputBehaviorInPlayMode);InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;originalKeyboard=Keyboard.current;originalMouse=Mouse.current;keyboard=InputSystem.AddDevice<Keyboard>();mouse=InputSystem.AddDevice<Mouse>();keyboard.MakeCurrent();mouse.MakeCurrent();Near(actor,iria);Advance(.7);break;
            case 2:point=camera.WorldToScreenPoint(iria.transform.position+Vector3.up*1.1f);MouseAt(point);Advance(.3);break;
            case 3:Check(input.HoveredWorld==iria.Target&&!input.HasSelection,"NPC mouseover is independent of selection");MouseAt(point,1);Advance(.15);break;
            case 4:MouseAt(point);Advance(.3);break;
            case 5:Check(input.SelectedWorld==iria.Target&&hud.SelectedNPC==iria.Target&&combat.TargetNetId==0,"Left-click selects NPC and clears hostile combat target");Check(!hud.TargetLife.gameObject.activeSelf&&hud.TargetStats.text==iria.Role,"NPC target card shows role rather than invented health");Check(!combat.ServerUse(0),"Friendly NPC cannot receive Warrior basic attacks");var marker=UnityEngine.Object.FindFirstObjectByType<RiftHUDTargetMarker>();Check(marker.Circle.sharedMaterial==hud.Theme.FriendlyTargetMaterial&&Mathf.Abs(marker.Circle.transform.position.y-iria.transform.position.y)<.4f,"NPC has a small green ground marker at its feet");Capture("npc-target");MouseAt(point,2);Advance(.15);break;
            case 6:MouseAt(point);Advance(.4);break;
            case 7:Check(RiftVillageUI.Instance.TalkingTo==iria,"Short right-click opens selected NPC dialogue");Check(!journal.ServerAccept("rift-scout","iria"),"Server rejects locked prerequisite quest");Check(!journal.ServerAccept("refuge-training","alma"),"Server rejects wrong/far quest giver");ButtonWith(RiftVillageUI.Instance.transform,"ACEPTAR MISIÓN").onClick.Invoke();Advance(.4);break;
            case 8:Check(journal.State.Quest("refuge-training")?.Status==QuestStatus.Active,"Real NPC acceptance command starts initial quest");Check(!journal.ServerTurnIn("refuge-training","iria"),"Server rejects turn-in before objectives are done");Check(journal.State.Count(new JournalObjective{Event=RiftProgressEvent.Talk,Unique=true})==1,"NPC conversation credited once for distinct-NPC achievement");RiftVillageUI.Instance.Close();dummy=GameManager.Players.Where(p=>p&&p.MyCharacter&&p.MyCharacter.Health.TrainingTarget).Select(p=>p.MyCharacter.Health).First();actor.ServerTeleport(dummy.transform.position-Vector3.forward*2.4f,0);input.CameraYaw=actor.Input.LookY=0;input.Select(dummy);Advance(.4);break;
            case 9:Capture("tracked-quest");Check(combat.ServerUse(0),"Training attack 1 accepted");Advance(1);break;
            case 10:Check(combat.ServerUse(0),"Training attack 2 accepted");Advance(1);break;
            case 11:Check(combat.ServerUse(0),"Training attack 3 accepted");Advance(1);break;
            case 12:Check(journal.State.Quest("refuge-training").Progress[0]==3,"Real training hits update quest objective");Check(journal.State.Count(new JournalObjective{Event=RiftProgressEvent.Kill})==0,"Training dummy does not count as an enemy kill");Check(journal.State.Achievements.Any(a=>a.Id=="first-training"),"Training achievement unlocks from combat event");Near(actor,bram);Advance(.4);break;
            case 13:RiftVillageUI.Instance.Open(bram);Advance(.4);break;
            case 14:Check(journal.State.Quest("refuge-training").Status==QuestStatus.Ready,"Talking to Bram completes remaining initial objective");Near(actor,iria);Advance(.4);break;
            case 15:RiftVillageUI.Instance.Open(iria);Advance(.4);break;
            case 16:Check(RiftJournalView.Offer("iria")=="?","Ready quest shows a turn-in marker");ButtonWith(RiftVillageUI.Instance.transform,"ENTREGAR").onClick.Invoke();Advance(.5);break;
            case 17:Check(journal.State.TurnedIn("refuge-training")&&RiftExplorationProgress.Gold==60,"Quest turn-in grants exactly 60 local gold");Check(journal.State.Achievements.Any(a=>a.Id=="first-quest"),"First completed quest unlocks achievement");Check(!journal.ServerTurnIn("refuge-training","iria"),"Repeated turn-in is rejected");RiftJournalView.ApplyServerSnapshot(JsonUtility.ToJson(journal.State),"");Check(RiftExplorationProgress.Gold==60,"Replayed snapshot cannot duplicate quest gold");Near(actor,alma);Advance(.4);break;
            case 18:RiftVillageUI.Instance.Open(alma);Advance(.4);break;
            case 19:Check(journal.ServerAccept("refuge-supplies","alma"),"Completed prerequisite unlocks supply quest");string message;Check(player.GetComponent<RiftVillagePlayer>().ServerVillageTrade("alma",0,false,out message),"Actual potion purchase succeeds with earned quest gold");actor.Health.Server_ChangeHealthStateRaw(60,0,AttackType.falldamage,actor.Health,0);Advance(.4);break;
            case 20:Check(player.GetComponent<RiftVillagePlayer>().ServerDrinkVillagePotion(out var potionMessage),"Actual potion consumption heals and advances quest");Advance(.4);break;
            case 21:Check(journal.State.Quest("refuge-supplies").Status==QuestStatus.Ready&&journal.ServerTurnIn("refuge-supplies","alma"),"Buying and using potion completes supply quest");Advance(.4);break;
            case 22:Check(RiftExplorationProgress.Gold==75,"Quest gold stays separate and potion purchase is deducted");Check(journal.State.Achievements.Any(a=>a.Id=="village-friends"),"Talking to three distinct NPCs unlocks social exploration achievement");Near(actor,iria);Advance(.4);break;
            case 23:Check(journal.ServerAccept("rift-scout","iria"),"Exploration quest can be accepted after tutorial");RiftVillageUI.Instance.Close();actor.Health.ServerSetVitals(10000,10000);encounter=world.Encounters.First(e=>e&&!e.MiniBoss&&e.SpawnPoints.Any(p=>p&&!world.IsSafe(p.position)));var spawnPoint=encounter.SpawnPoints.First(p=>p&&!world.IsSafe(p.position));actor.ServerTeleport(spawnPoint.position,0);Advance(5);break;
            case 24:Check(KillEncounterEnemies(actor)>=5,"Actual spawned encounter enemies can be defeated for quest progress");Advance(.6);break;
            case 25:Check(journal.State.Quest("rift-scout").Progress[0]==5&&journal.State.Achievements.Any(a=>a.Id=="first-kill"),"Real encounter kills update quest and first-victory achievement");crystals=world.Checkpoints.Where(c=>c&&!c.StartingCamp).Take(3).ToArray();actor.ServerTeleport(crystals[0].Respawn.position,0);Advance(.7);break;
            case 26:Check(journal.State.Quest("rift-scout").Status==QuestStatus.Ready,"Actual non-starting checkpoint completes exploration objective");Near(actor,iria);Advance(.4);break;
            case 27:Check(journal.ServerTurnIn("rift-scout","iria"),"Exploration quest turns in at its giver");Near(actor,bram);Advance(.4);break;
            case 28:Check(journal.ServerAccept("rift-guardian","bram"),"Guardian quest unlocks through quest chain");bossDeadline=EditorApplication.timeSinceStartup+45;boss=world.Encounters.First(e=>e&&e.MiniBoss&&!e.Cleared&&e.SpawnPoints.Any(p=>p&&!world.IsSafe(p.position)));actor.ServerTeleport(boss.SpawnPoints.First(p=>p&&!world.IsSafe(p.position)).position,0);Advance(8);break;
            case 29:Check(KillEncounterEnemies(actor)>0,"Boss encounter spawns actual enemies");Advance(.7);break;
            case 30:if(journal.State.Quest("rift-guardian").Status!=QuestStatus.Ready&&EditorApplication.timeSinceStartup<bossDeadline){report.Add("Boss diagnostics spawned="+boss.Spawned+" / "+boss.Count+" defeated="+boss.Defeated+" quest="+string.Join(",",journal.State.Quest("rift-guardian").Progress));KillEncounterEnemies(actor);next=EditorApplication.timeSinceStartup+1;return;}Check(journal.State.Quest("rift-guardian").Status==QuestStatus.Ready&&journal.State.Achievements.Any(a=>a.Id=="first-boss"),"Actual boss death and encounter clear complete guardian quest");Near(actor,bram);Advance(.4);break;
            case 31:Check(journal.ServerTurnIn("rift-guardian","bram"),"Guardian quest rewards can be claimed");actor.ServerTeleport(crystals[1].Respawn.position,0);Advance(.7);break;
            case 32:actor.ServerTeleport(crystals[2].Respawn.position,0);Advance(.7);break;
            case 33:Check(journal.State.Achievements.Any(a=>a.Id=="three-crystals"),"Three actual distinct checkpoints unlock exploration achievement");actor.ServerTeleport(crystals[1].Respawn.position,0);Advance(.7);break;
            case 34:Check(journal.State.Count(new JournalObjective{Event=RiftProgressEvent.Checkpoint,Unique=true})==3,"Revisiting a checkpoint does not farm distinct progress");var saved=JsonUtility.FromJson<JournalState>(File.ReadAllText(Directory.GetFiles(RiftJournalPlayer.StorageOverride,"*.json").Single()));Check(saved.CharacterId==testId&&saved.Quests.Count(q=>q.Status==QuestStatus.TurnedIn)==4,"Host persistence retains all four completed quests by character identity");Check(RiftJournalView.Read("other-"+testId).Quests.Count==0,"Another character has independent progress");Check(RiftJournalView.Read(testId).Quests.Count==4,"Offline cache reload retains character journal");Press(UnityEngine.InputSystem.Key.J);Advance(.4);break;
            case 35:Check(UIPauseMenu._instance.pauseMenuShowing&&UIPauseMenu._instance.pauseMenuOverlay.GetComponentInChildren<RiftHub>().Page==HubPage.Missions,"Rebindable J shortcut opens real quest journal");Press();var questHub=UIPauseMenu._instance.pauseMenuOverlay.GetComponentInChildren<RiftHub>();questHub.GetComponentsInChildren<Dropdown>().First(d=>d.options.Any(o=>o.text=="Completadas")).value=1;Advance(.3);break;
            case 36:Capture("quest-journal");UIPauseMenu._instance.pauseMenuOverlay.GetComponentInChildren<RiftHub>().ShowAchievements();Advance(.3);break;
            case 37:Check(UIPauseMenu._instance.pauseMenuOverlay.GetComponentInChildren<RiftHub>().Page==HubPage.Progression,"Achievements page is accessible");Capture("achievements");Check(journal.State.Achievements.All(a=>a.UnlockedAt>0),"Achievement unlock timestamps are persisted");UIPauseMenu._instance.ShowPauseMenu(false);Finish(true);break;
            }
        }catch(Exception e){Debug.LogException(e);report.Add(e.ToString());Finish(false);}}
        static int KillEncounterEnemies(CharacterInstance actor){var enemies=(System.Collections.IDictionary)typeof(ROM.Horde.Horde).GetField("_encounterByEnemy",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(ROM.Horde.Horde.Instance);int count=0;foreach(var health in enemies.Keys.Cast<Health>().ToArray())if(health&&health.CurrentHealth>0&&Vector3.Distance(health.transform.position,actor.transform.position)<180){health.Server_ChangeHealthStateRaw(999999,0,AttackType.explosion,actor.Health,0);if(health.CurrentHealth<=0)count++;}return count;}
        static void Capture(string name)=>typeof(RiftGameplayHUDProbe).GetMethod("CaptureGame",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{Folder+"/"+name+".png",1920,1080});
        static void Finish(bool ok){if(keyboard!=null){InputSystem.RemoveDevice(keyboard);InputSystem.RemoveDevice(mouse);keyboard=null;mouse=null;if(originalKeyboard!=null)originalKeyboard.MakeCurrent();if(originalMouse!=null)originalMouse.MakeCurrent();InputSystem.settings.backgroundBehavior=(InputSettings.BackgroundBehavior)SessionState.GetInt(Key+"Background",0);InputSystem.settings.editorInputBehaviorInPlayMode=(InputSettings.EditorInputBehaviorInPlayMode)SessionState.GetInt(Key+"Editor",0);}File.WriteAllLines(Folder+"/validation.txt",report);SessionState.SetInt(Key+"Result",ok?0:1);EditorApplication.update-=Tick;EditorApplication.isPlaying=false;}
    }
}
